235	    @Override
236	    @Transactional
237	    public void saveOwner(Owner owner) throws DataAccessException {
238	        if (owner.isNew()) {
239	            if (owner.getRegistrationDate() == null) {
240	                owner.setRegistrationDate(LocalDate.now());
241	            }
242	            if (isDailyRegistrationLimitReached(owner)) {
243	                throw new OwnerRegistrationLimitException(
244	                    "The maximum number of owners that can be registered today has been reached");
245	            }
246	            owner.setCity(resolveCity(owner));
247	            owner.setMembershipNumber(ownerRepository.findAll().size() + 1);
248	            owner.setCustomerCode(generateCustomerCode(owner));
249	            if (isDuplicateTelephone(owner)) {
250	                throw new DuplicateOwnerException(
251	                    "An owner with the same telephone already exists");
252	            }
253	            if (isDuplicateEmail(owner)) {
254	                throw new DuplicateOwnerException(
255	                    "An owner with the same email already exists");
256	            }
257	        }
258	        ownerRepository.save(owner);
259	
260	    }
261	
262	    /**
263	     * Build a customer code for a newly created owner, formatted as
264	     * {@code <UPPERCASE_CITY>-<NNNN>} where NNNN is one more than the number of
265	     * owners already registered in that city, zero-padded to four digits
266	     * (e.g. {@code LONDON-0007}).
267	     */
268	    private String generateCustomerCode(Owner owner) {
269	        String city = owner.getCity();
270	        long existingInCity = ownerRepository.findAll().stream()
271	            .filter(existing -> !existing.getId().equals(owner.getId()))
272	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
273	            .count();
274	        String prefix = city == null ? "" : city.toUpperCase(Locale.ROOT);
275	        return String.format("%s-%04d", prefix, existingInCity + 1);
276	    }
277	
278	    /**
279	     * Determine the city to store for a newly created owner. If another owner is
280	     * already registered in the same city (compared case-insensitively), reuse
281	     * that owner's exact spelling of the city name so the whole clinic agrees on
282	     * one canonical form. Otherwise the supplied city is title-cased (each
283	     * whitespace-separated word capitalised, e.g. "new york" becomes
284	     * "New York"). A {@code null} city stays {@code null}.
285	     */
286	    private String resolveCity(Owner owner) {
287	        String city = owner.getCity();
288	        if (city == null) {
289	            return null;
290	        }
291	        return ownerRepository.findAll().stream()
292	            .filter(existing -> !existing.getId().equals(owner.getId()))
293	            .map(Owner::getCity)
294	            .filter(existingCity -> existingCity != null && existingCity.equalsIgnoreCase(city))
295	            .findFirst()
296	            .orElseGet(() -> toTitleCase(city));
297	    }
298	
299	    /**
300	     * Title-case a value by upper-casing the first letter of every
301	     * whitespace-separated word and lower-casing the remaining letters, while
302	     * preserving the original whitespace. A {@code null} value stays
303	     * {@code null}.
304	     */
305	    private static String toTitleCase(String value) {
306	        if (value == null) {
307	            return null;
308	        }
309	        StringBuilder result = new StringBuilder(value.length());
310	        boolean startOfWord = true;
311	        for (int i = 0; i < value.length(); i++) {
312	            char c = value.charAt(i);
313	            if (Character.isWhitespace(c)) {
314	                startOfWord = true;
315	                result.append(c);
316	            } else if (startOfWord) {
317	                result.append(Character.toTitleCase(Character.toLowerCase(c)));
318	                startOfWord = false;
319	            } else {
320	                result.append(Character.toLowerCase(c));
321	            }
322	        }
323	        return result.toString();
324	    }
325	
326	    /**
327	     * The maximum number of owners that may be registered on any single day (by registration date).
328	     */
329	    private static final int MAX_OWNERS_PER_DAY = 20;
330	
331	    /**
332	     * Determine whether the daily registration limit has already been reached for the day the given
333	     * owner is being registered on. Counts the existing owners whose registration date matches the new
334	     * owner's registration date and returns {@code true} once that count has reached
335	     * {@link #MAX_OWNERS_PER_DAY}.
336	     */
337	    private boolean isDailyRegistrationLimitReached(Owner owner) {
338	        LocalDate registrationDate = owner.getRegistrationDate();
339	        if (registrationDate == null) {
340	            return false;
341	        }
342	        long registeredToday = ownerRepository.findAll().stream()
343	            .filter(existing -> !existing.getId().equals(owner.getId()))
344	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
345	            .count();
346	        return registeredToday >= MAX_OWNERS_PER_DAY;
347	    }
348	
349	    private boolean isDuplicateTelephone(Owner owner) {
350	        String telephone = normalizeTelephone(owner.getTelephone());
351	        return ownerRepository.findAll().stream()
352	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
353	                && Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
354	    }
355	
356	    /**
357	     * Normalize a telephone number for duplicate detection by stripping every
358	     * character that is not a digit (spaces, dashes and parentheses), so that
359	     * "(613) 555-0100" and "6135550100" are treated as the same number. A
360	     * {@code null} value stays {@code null}.
361	     */
362	    private static String normalizeTelephone(String value) {
363	        if (value == null) {
364	            return null;
365	        }
366	        return value.replaceAll("[^0-9]", "");
367	    }
368	
369	    private boolean isDuplicateEmail(Owner owner) {
370	        String email = owner.getEmail();
371	        if (email == null || email.isBlank()) {
372	            return false;
373	        }
374	        String normalizedEmail = normalize(email);
375	        return ownerRepository.findAll().stream()
376	            .anyMatch(existing -> !existing.getId().equals(owner.getId())
377	                && Objects.equals(normalize(existing.getEmail()), normalizedEmail));
378	    }
379	
380	    /**
381	     * Normalize a textual value for duplicate detection so that comparisons
382	     * ignore letter case and surrounding or repeated whitespace. A {@code null}
383	     * value stays {@code null}; otherwise surrounding whitespace is trimmed, any
384	     * run of internal whitespace is collapsed to a single space, and letters are
385	     * lower-cased. For example "  john   smith " and "John Smith" normalize to
386	     * the same value and therefore count as the same person.
387	     */
388	    private static String normalize(String value) {
389	        if (value == null) {
390	            return null;
391	        }
392	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
393	    }
394	
395	    @Override
