398	        return ownerRepository.findByLastName(lastName);
399	    }
400	
401	    @Override
402	    @Transactional(readOnly = true)
403	    public Collection<Visit> findVisitsByPetId(int petId) {
404	        return visitRepository.findByPetId(petId);
405	    }
406	
407	    @Override
408	    @Transactional(readOnly = true)
409	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
410	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
411	    }
412	
413	    private <T> T findEntityById(Supplier<T> supplier) {
414	        try {
415	            return supplier.get();
416	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
417	            // Just ignore not found exceptions for Jdbc/Jpa realization
418	            return null;
419	        }
420	    }
421	
422	}
